"""Loads `prompts/<agent>_<step>.md` at runtime and fills `{{placeholders}}`."""

from __future__ import annotations

import re
from functools import lru_cache
from pathlib import Path

from src.models.evidence import ProductBrief

from .taxonomy import Taxonomy

PROMPT_DIR = Path(__file__).with_name("prompts")
_PLACEHOLDER = re.compile(r"\{\{(\w+)\}\}")


@lru_cache(maxsize=None)
def _read(name: str) -> str:
    return (PROMPT_DIR / f"{name}.md").read_text()


def render_brief(brief: ProductBrief) -> str:
    lines = [
        f"- Product: {brief.product}",
        f"- Segment: {brief.segment}",
        f"- Target markets: {', '.join(brief.target_markets) or 'n/a'}",
        f"- Target customers: {brief.target_customers or 'n/a'}",
        f"- Predecessor model: {brief.predecessor_model or 'none'}",
        f"- Known competitors: {', '.join(brief.known_competitors) or 'none given'}",
        f"- Focus areas: {', '.join(brief.focus_areas) or 'all'}",
    ]
    if brief.notes:
        lines.append(f"- Notes: {brief.notes}")
    return "\n".join(lines)


def render_prompt(name: str, *, brief: ProductBrief, taxonomy: Taxonomy, **values: object) -> str:
    text = _read(name).replace("{{common_rules}}", _read("_common_rules"))
    values = {"brief": render_brief(brief), "taxonomy": taxonomy.render(), **values}

    def sub(m: re.Match[str]) -> str:
        key = m.group(1)
        if key not in values:
            raise KeyError(f"prompt {name!r} needs {{{{{key}}}}}")
        return str(values[key])

    return _PLACEHOLDER.sub(sub, text)

"""Ontology contracts (§4.1) as source-producing functions and LangChain tools."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Generic, TypeVar

from langchain_core.tools import BaseTool, StructuredTool

from src.models.evidence import Source

from ..sources import Budget, SourceRegistry, doc_source, model_source
from .knowledge import AttributeValue, DocChunk, FeedbackFilter, FeedbackItem, ModelNode, get_backend

T = TypeVar("T")


@dataclass
class Retrieved(Generic[T]):
    data: T
    sources: list[Source] = field(default_factory=list)


async def get_model(model_code: str) -> Retrieved[ModelNode | None]:
    model = await get_backend().get_model(model_code)
    return Retrieved(model, [model_source(model)] if model is not None else [])


async def list_portfolio(segment: str | None, regions: list[str]) -> Retrieved[list[ModelNode]]:
    models = await get_backend().list_portfolio(segment, regions)
    return Retrieved(models, [model_source(m) for m in models])


async def list_competitor_models(segment: str, regions: list[str],
                                 names: list[str] | None = None) -> Retrieved[list[ModelNode]]:
    models = await get_backend().list_competitor_models(segment, regions, names or None)
    return Retrieved(models, [model_source(m) for m in models])


async def get_attribute_values(model_id: str, attributes: list[str] | None = None) -> Retrieved[list[AttributeValue]]:
    # Sources need the model name for rendering; callers build them with sources.attribute_source.
    return Retrieved(await get_backend().get_attribute_values(model_id, attributes))


async def get_feedback_items(filters: FeedbackFilter) -> Retrieved[list[FeedbackItem]]:
    # Sources for feedback are created per representative item by the feedback agent.
    return Retrieved(await get_backend().get_feedback_items(filters))


async def search_documents(query: str, kinds: list[str] | None, regions: list[str],
                           k: int = 10) -> Retrieved[list[DocChunk]]:
    chunks = await get_backend().search_documents(query, kinds, regions, k)
    return Retrieved(chunks, [doc_source(c) for c in chunks])


def render_chunks(chunks: list[DocChunk], max_chars: int = 900) -> str:
    if not chunks:
        return "No matching documents in the knowledge layer."
    parts = []
    for c in chunks:
        text = c.text if len(c.text) <= max_chars else c.text[:max_chars] + "…"
        parts.append(f"[kg:{c.node_id}] {c.doc_title} ({c.published or 'n.d.'})\n{text}")
    return "\n\n".join(parts)


def make_graph_tools(registry: SourceRegistry, budget: Budget, regions: list[str]) -> list[BaseTool]:
    """Tools for bounded agent loops, scoped to the run's regions. Results show citable source ids."""

    async def _search_documents(query: str, k: int = 6) -> str:
        if not budget.take("call"):
            return "BUDGET EXHAUSTED: stop calling tools and return your final answer now."
        chunks = await get_backend().search_documents(query, ["study", "report"], regions, min(k, 10))
        for c in chunks:
            registry.add(doc_source(c), full_text=c.text)
        return render_chunks(chunks)

    return [
        StructuredTool.from_function(
            coroutine=_search_documents,
            name="search_documents",
            description="Search studies and reports stored in the knowledge layer. Returns chunks with citable ids [kg:...].",
        )
    ]

